<header class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/paragraph {"className":"is-style-eyebrow","style":{"typography":{"textAlign":"center"}}} -->
<p class="has-text-align-center wp-block-paragraph is-style-eyebrow">Mission &amp; values</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/heading {"style":{"typography":{"textAlign":"center"}}} -->
<h2 class="wp-block-heading has-text-align-center">What we believe</h2>
<!-- /wp:artisanpack/heading -->

<!-- wp:artisanpack/paragraph {"className":"is-style-lead","style":{"typography":{"textAlign":"center"},"spacing":{"margin":{"top":"1.625rem"}}}} -->
<p class="has-text-align-center wp-block-paragraph is-style-lead" style="margin-top:1.625rem">Four principles guide every decision, every package and every line of code in the ecosystem.</p>
<!-- /wp:artisanpack/paragraph --></header>
<!-- /wp:artisanpack/group -->

<!-- wp:artisanpack/grid {"numColumns":2,"style":{"spacing":{"blockGap":"1.375rem"}}} -->
<div class="wp-block-artisanpack-grid ap-grid ap-grid-has-2-base-columns ap-grid-layout-fixed"><!-- wp:artisanpack/grid-item {"borderColor":"primary","className":"is-style-boxed"} -->
<div class="wp-block-artisanpack-grid-item ap-grid-item ap-grid-item-layout-normal ap-grid-item-span-1-base-columns ap-grid-item-span-1-base-row is-style-boxed has-border-color has-primary-border-color"><!-- wp:artisanpack/group {"style":{"spacing":{"blockGap":"0.875rem"}},"layout":{"type":"default"}} -->
<div class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/icon {"iconRef":{"set":"fas","name":"universal-access"},"size":22,"backgroundColor":"primary-tint","iconColor":"#2962FF","isDecorative":true,"className":"is-style-tile"} /-->

<!-- wp:artisanpack/heading {"level":3,"fontSize":"card-title","style":{"typography":{"lineHeight":"1.65"}}} -->
<h3 class="wp-block-heading has-card-title-font-size" style="line-height:1.65">Accessibility first</h3>
<!-- /wp:artisanpack/heading -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","fontSize":"body-sm"} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color has-body-sm-font-size">Accessibility isn't a feature to add later — it's a foundation to build on. Every ArtisanPack UI component ships with proper ARIA attributes, keyboard navigation and focus management. Not because regulations require it, but because everyone deserves to use the web.</p>
<!-- /wp:artisanpack/paragraph --></div>
<!-- /wp:artisanpack/group --></div>
<!-- /wp:artisanpack/grid-item -->

<!-- wp:artisanpack/grid-item {"borderColor":"secondary","className":"is-style-boxed"} -->
<div class="wp-block-artisanpack-grid-item ap-grid-item ap-grid-item-layout-normal ap-grid-item-span-1-base-columns ap-grid-item-span-1-base-row is-style-boxed has-border-color has-secondary-border-color"><!-- wp:artisanpack/group {"style":{"spacing":{"blockGap":"0.875rem"}},"layout":{"type":"default"}} -->
<div class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/icon {"iconRef":{"set":"fas","name":"wand-magic-sparkles"},"size":22,"backgroundColor":"secondary-tint","iconColor":"#00E5FF","isDecorative":true,"className":"is-style-tile"} /-->

<!-- wp:artisanpack/heading {"level":3,"fontSize":"card-title","style":{"typography":{"lineHeight":"1.65"}}} -->
<h3 class="wp-block-heading has-card-title-font-size" style="line-height:1.65">Developer empowerment</h3>
<!-- /wp:artisanpack/heading -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","fontSize":"body-sm"} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color has-body-sm-font-size">The best tools get out of your way. ArtisanPack UI handles the repetitive work so developers can focus on what makes their projects unique. Less time rebuilding basics means more time building features that matter.</p>
<!-- /wp:artisanpack/paragraph --></div>
<!-- /wp:artisanpack/group --></div>
<!-- /wp:artisanpack/grid-item -->

<!-- wp:artisanpack/grid-item {"borderColor":"accent","className":"is-style-boxed"} -->
<div class="wp-block-artisanpack-grid-item ap-grid-item ap-grid-item-layout-normal ap-grid-item-span-1-base-columns ap-grid-item-span-1-base-row is-style-boxed has-border-color has-accent-border-color"><!-- wp:artisanpack/group {"style":{"spacing":{"blockGap":"0.875rem"}},"layout":{"type":"default"}} -->
<div class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/icon {"iconRef":{"set":"fas","name":"code-branch"},"size":22,"backgroundColor":"accent-tint","iconColor":"#E040FB","isDecorative":true,"className":"is-style-tile"} /-->

<!-- wp:artisanpack/heading {"level":3,"fontSize":"card-title","style":{"typography":{"lineHeight":"1.65"}}} -->
<h3 class="wp-block-heading has-card-title-font-size" style="line-height:1.65">Open source always</h3>
<!-- /wp:artisanpack/heading -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","fontSize":"body-sm"} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color has-body-sm-font-size">ArtisanPack UI is MIT licensed and always will be. The code is on GitHub for anyone to use, modify and contribute to. Open source isn't just a license — it's a commitment to the community that made Laravel great.</p>
<!-- /wp:artisanpack/paragraph --></div>
<!-- /wp:artisanpack/group --></div>
<!-- /wp:artisanpack/grid-item -->

<!-- wp:artisanpack/grid-item {"className":"is-style-boxed","style":{"border":{"width":"3px","style":"solid","radius":"12px","gradient":"neon"}}} -->
<div class="wp-block-artisanpack-grid-item ap-grid-item ap-grid-item-layout-normal ap-grid-item-span-1-base-columns ap-grid-item-span-1-base-row is-style-boxed" style="border-style:solid;border-width:3px;border-radius:12px"><!-- wp:artisanpack/group {"style":{"spacing":{"blockGap":"0.875rem"}},"layout":{"type":"default"}} -->
<div class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/icon {"iconRef":{"set":"fas","name":"screwdriver-wrench"},"size":22,"iconColor":"#FFFFFF","isDecorative":true,"gradient":"brand","className":"is-style-tile"} /-->

<!-- wp:artisanpack/heading {"level":3,"fontSize":"card-title","style":{"typography":{"lineHeight":"1.65"}}} -->
<h3 class="wp-block-heading has-card-title-font-size" style="line-height:1.65">Practical over perfect</h3>
<!-- /wp:artisanpack/heading -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","fontSize":"body-sm"} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color has-body-sm-font-size">Real developers ship real projects with real deadlines. ArtisanPack UI prioritizes practical solutions that work today over theoretical ideals that might work someday. Every feature exists because it solves a problem someone actually had.</p>
<!-- /wp:artisanpack/paragraph --></div>
<!-- /wp:artisanpack/group --></div>
<!-- /wp:artisanpack/grid-item --></div>
<!-- /wp:artisanpack/grid --></section>
<!-- /wp:artisanpack/group -->

<!-- wp:artisanpack/group {"tagName":"section","backgroundColor":"base","align":"full","style":{"spacing":{"padding":{"top":"var:preset|spacing|section","bottom":"var:preset|spacing|section","left":"var:preset|spacing|gutter","right":"var:preset|spacing|gutter"},"blockGap":"var:preset|spacing|title-gap"}},"layout":{"type":"constrained","contentSize":"1200px"}} -->
