<div class="wp-block-artisanpack-column wp-block-column is-vertically-aligned-center"><!-- wp:artisanpack/group {"style":{"spacing":{"blockGap":"1.5rem"}},"layout":{"type":"default"}} -->
<div class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/group {"tagName":"header","style":{"spacing":{"blockGap":"1.25rem"}},"layout":{"type":"default"}} -->
<header class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/paragraph {"className":"is-style-eyebrow"} -->
<p class="wp-block-paragraph is-style-eyebrow">The maker</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/heading -->
<h2 class="wp-block-heading">The developer behind ArtisanPack UI</h2>
<!-- /wp:artisanpack/heading --></header>
<!-- /wp:artisanpack/group -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","style":{"typography":{"fontSize":"1rem","lineHeight":"1.7"}}} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color" style="font-size:1rem;line-height:1.7">ArtisanPack UI is built and maintained by a developer with over a decade of experience building for the web. After years working with WordPress and watching its hooks system enable incredible extensibility, the transition to Laravel left one thing missing: that familiar pattern of actions and filters that made WordPress so customizable.</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","style":{"typography":{"fontSize":"1rem","lineHeight":"1.7"}}} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color" style="font-size:1rem;line-height:1.7">That gap inspired the <strong>Hooks</strong> package, which brought WordPress-style extensibility to Laravel. From there, the ecosystem grew organically — each new package solving a problem encountered in client work and freelance projects.</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","style":{"typography":{"fontSize":"1rem","lineHeight":"1.7"}}} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color" style="font-size:1rem;line-height:1.7">A background in journalism instilled a commitment to clear communication and attention to detail. (You might notice the consistent use of AP style throughout the documentation.) That same discipline applies to code: clean, well-documented and built to last.</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/group {"backgroundColor":"surface","style":{"border":{"top":{"color":"var:preset|color|border-subtle","width":"1px","style":"solid"},"right":{"color":"var:preset|color|border-subtle","width":"1px","style":"solid"},"bottom":{"color":"var:preset|color|border-subtle","width":"1px","style":"solid"},"left":{"color":"var:preset|color|secondary","width":"3px","style":"solid"},"radius":"12px"},"spacing":{"padding":{"top":"1.375rem","bottom":"1.375rem","left":"1.5rem","right":"1.5rem"},"blockGap":"0.5rem"},"shadow":"var:preset|shadow|sm"},"layout":{"type":"default"}} -->
<div class="wp-block-artisanpack-group wp-block-group has-surface-background-color has-background" style="border-radius:12px;border-top-color:var(--wp--preset--color--border-subtle);border-top-style:solid;border-top-width:1px;border-right-color:var(--wp--preset--color--border-subtle);border-right-style:solid;border-right-width:1px;border-bottom-color:var(--wp--preset--color--border-subtle);border-bottom-style:solid;border-bottom-width:1px;border-left-color:var(--wp--preset--color--secondary);border-left-style:solid;border-left-width:3px;padding-top:1.375rem;padding-right:1.5rem;padding-bottom:1.375rem;padding-left:1.5rem;box-shadow:var(--wp--preset--shadow--sm)"><!-- wp:artisanpack/paragraph {"textColor":"text-link","fontFamily":"mono","style":{"typography":{"fontSize":"0.75rem","letterSpacing":"0.04em","textTransform":"uppercase"}}} -->
<p class="wp-block-paragraph has-text-link-color has-text-color has-mono-font-family" style="font-size:0.75rem;letter-spacing:0.04em;text-transform:uppercase">Current focus</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","style":{"typography":{"fontSize":"0.9375rem","lineHeight":"1.65"}}} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color" style="font-size:0.9375rem;line-height:1.65">Today, development continues on expanding the ecosystem while maintaining the packages that developers already rely on. The goal remains the same: build tools that make Laravel development faster without sacrificing quality or accessibility.</p>
<!-- /wp:artisanpack/paragraph --></div>
<!-- /wp:artisanpack/group --></div>
<!-- /wp:artisanpack/group --></div>
<!-- /wp:artisanpack/column -->

