<p class="wp-block-paragraph has-text-link-color has-text-color has-mono-font-family" style="font-size:0.75rem;letter-spacing:0.04em;text-transform:uppercase">Maintained by</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/paragraph {"textColor":"text","fontFamily":"display","style":{"typography":{"fontSize":"1.5rem","fontWeight":"700","letterSpacing":"-0.01em","lineHeight":"1.25"}}} -->
<p class="wp-block-paragraph has-text-color has-display-font-family" style="font-size:1.5rem;font-weight:700;letter-spacing:-0.01em;line-height:1.25">Jacob Martella Web Design</p>
<!-- /wp:artisanpack/paragraph --></div>
