<!-- wp:artisanpack/paragraph {"textColor":"text-muted","style":{"typography":{"fontSize":"0.90625rem","lineHeight":"1.65"}}} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color" style="font-size:0.90625rem;line-height:1.65">ArtisanPack UI is a Jacob Martella Web Design project — an independent studio building thoughtful, accessible tools for the Laravel community.</p>
<!-- /wp:artisanpack/paragraph -->

<!-- wp:artisanpack/group {"artisanpackFlex":{"container":{"enabled":{"base":true},"direction":{"base":"row"},"wrap":{"base":"wrap"},"alignItems":{"base":"center"}}},"style":{"spacing":{"blockGap":"0.625rem","margin":{"top":"0.25rem"}}}} -->
