<div class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/icon {"iconRef":{"set":"fas","name":"bug"},"size":22,"backgroundColor":"primary-tint","iconColor":"#2962FF","isDecorative":true,"className":"is-style-tile"} /-->

<!-- wp:artisanpack/heading {"level":3,"fontSize":"card-title","style":{"typography":{"lineHeight":"1.65"}}} -->
<h3 class="wp-block-heading has-card-title-font-size" style="line-height:1.65">Report issues</h3>
<!-- /wp:artisanpack/heading -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","fontSize":"body-sm"} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color has-body-sm-font-size">Found a bug? Have a feature request? Open an issue on GitHub. Clear descriptions and reproduction steps help get things fixed faster.</p>
<!-- /wp:artisanpack/paragraph --></div>
<!-- /wp:artisanpack/group --></div>
<!-- /wp:artisanpack/grid-item -->

<!-- wp:artisanpack/grid-item {"className":"is-style-boxed"} -->
<div class="wp-block-artisanpack-grid-item ap-grid-item ap-grid-item-layout-normal ap-grid-item-span-1-base-columns ap-grid-item-span-1-base-row is-style-boxed"><!-- wp:artisanpack/group {"style":{"spacing":{"blockGap":"0.875rem"}},"layout":{"type":"default"}} -->
<div class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/icon {"iconRef":{"set":"fas","name":"code-pull-request"},"size":22,"backgroundColor":"secondary-tint","iconColor":"#00E5FF","isDecorative":true,"className":"is-style-tile"} /-->

<!-- wp:artisanpack/heading {"level":3,"fontSize":"card-title","style":{"typography":{"lineHeight":"1.65"}}} -->
<h3 class="wp-block-heading has-card-title-font-size" style="line-height:1.65">Submit code</h3>
<!-- /wp:artisanpack/heading -->

<!-- wp:artisanpack/paragraph {"textColor":"text-muted","fontSize":"body-sm"} -->
<p class="wp-block-paragraph has-text-muted-color has-text-color has-body-sm-font-size">Pull requests are welcome for bug fixes, new features and documentation improvements. Check the contributing guide in each repository for guidelines.</p>
<!-- /wp:artisanpack/paragraph --></div>
<!-- /wp:artisanpack/group --></div>
<!-- /wp:artisanpack/grid-item -->

<!-- wp:artisanpack/grid-item {"className":"is-style-boxed"} -->
<div class="wp-block-artisanpack-grid-item ap-grid-item ap-grid-item-layout-normal ap-grid-item-span-1-base-columns ap-grid-item-span-1-base-row is-style-boxed"><!-- wp:artisanpack/group {"style":{"spacing":{"blockGap":"0.875rem"}},"layout":{"type":"default"}} -->
<div class="wp-block-artisanpack-group wp-block-group"><!-- wp:artisanpack/icon {"iconRef":{"set":"fas","name":"comment-dots"},"size":22,"backgroundColor":"accent-tint","iconColor":"#E040FB","isDecorative":true,"className":"is-style-tile"} /-->

<!-- wp:artisanpack/heading {"level":3,"fontSize":"card-title","style":{"typography":{"lineHeight":"1.65"}}} -->
